() => {
  const main = document.querySelector('main');
  if (main) { main.scrollTop = 0; return 'scrolled main to top, scrollHeight=' + main.scrollHeight; }
  return 'main not found';
}

() => {
  const els = document.querySelectorAll('main *');
  const scrollables = [];
  els.forEach(el => {
    if (el.scrollHeight > el.clientHeight + 50) {
      scrollables.push({tag: el.tagName, cls: (el.className||'').toString().slice(0,60), sh: el.scrollHeight, ch: el.clientHeight});
    }
  });
  if (scrollables.length) {
    const first = els[0];
    // scroll all scrollables to top
    els.forEach(el => { if (el.scrollHeight > el.clientHeight + 50) el.scrollTop = 0; });
  }
  return scrollables;
}

